package cn.lvxu.travel;
import android.app.*;import android.content.*;import android.os.SystemClock;import android.view.accessibility.AccessibilityNodeInfo;import java.time.LocalDate;import java.util.*;
/** Independent 0.4.0 smoke tests, invoked by the root runner when desired. */
final class Features040Tests{
 private static int n;private static void ok(boolean v,String s){if(!v)throw new AssertionError(s);n++;}
 static int run(Instrumentation in)throws Exception{n=0;Context c=in.getTargetContext();SharedPreferences ts=c.getSharedPreferences(TagRepository.PREF,0);Map<String,?> old=new HashMap<>(ts.getAll());ApiConfig cfg=new ApiConfig(c);org.json.JSONObject previousConfig=cfg.read();MainActivity a=null;try{cfg.reset();c.getSharedPreferences("app-prefs-v2",0).edit().putBoolean("tutorial",true).apply();a=(MainActivity)in.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));final MainActivity host=a;UiAutomation ui=in.getUiAutomation();in.runOnMainSync(()->new AboutUi(host,()->{}).show());wait(ui,"关于");capture(in,"040-about.png");ui.performGlobalAction(1);SystemClock.sleep(150);ok(find(ui.getRootInActiveWindow(),"关于")==null,"About back closes");boolean auto=AboutUi.autoUpdates(c);c.getSharedPreferences("about-support-v1",0).edit().putBoolean("auto-update",!auto).apply();ok(AboutUi.autoUpdates(c)!=auto,"auto update toggle");c.getSharedPreferences("about-support-v1",0).edit().putBoolean("auto-update",auto).apply();TagRepository r=new TagRepository(c);int preset=r.all().size();ok(preset>=33,"preset tags");TagRepository.Group g=r.createGroup("测试组040","说明");TagRepository.Tag t=r.create("测试标签040",TagRepository.DEFAULT_COLOR,Collections.singletonList(g.id));r.rename(t.id,"测试标签040改名",0xff123456);ok(r.inGroup(g.id).size()==1,"tag CRUD");r.delete(t.id,host.trips);r.deleteGroup(g.id);ok(r.all().size()==preset,"preset tags retained");Trip trip=new Trip();trip.title="搜索";trip.start="2026-04-01";trip.days=2;Trip.Stop stop=new Trip.Stop();stop.name="西湖";stop.note="春日拍照";stop.day=0;trip.stops.add(stop);SearchIndex.Query q=new SearchIndex.Query();q.text="拍照";ok(SearchIndex.search(Collections.singletonList(trip),q).size()==1,"notes search");q.text="";q.type="地点";q.from=LocalDate.of(2026,4,1);q.to=q.from;ok(SearchIndex.search(Collections.singletonList(trip),q).size()==1,"date filter");q.from=LocalDate.of(2026,5,1);ok(SearchIndex.search(Collections.singletonList(trip),q).isEmpty(),"date excludes");ok(cfg.mapKey("amap").isEmpty()&&cfg.searchKey().isEmpty(),"blank API defaults");cfg.put("mapKey.amap","local-test");new WebDavService(c).clear();ok(cfg.mapKey("amap").equals("local-test"),"WebDAV keeps API config");cfg.reset();in.runOnMainSync(()->new ExploreUi(host).show());wait(ui,"那年今日");wait(ui,"AI 搜索");wait(ui,"AI 规划");ok(find(ui.getRootInActiveWindow(),"AI 规划")!=null,"explore entries");capture(in,"040-explore.png");ui.performGlobalAction(1);SystemClock.sleep(300);in.runOnMainSync(()->new AdvancedSettingsUi(host).show());wait(ui,"高级设置");capture(in,"040-advanced.png");ui.performGlobalAction(1);SystemClock.sleep(300);SharedPreferences releases=c.getSharedPreferences("release-notes",0);String marker=ReleaseNotes.markerKey(c,"0.4.0");releases.edit().remove(marker).commit();in.runOnMainSync(()->ReleaseNotes.showIfNeeded(host,"0.4.0"));wait(ui,"更新日志");ui.performGlobalAction(1);SystemClock.sleep(300);ok(releases.getBoolean(marker,false),"release back acknowledges current version");in.runOnMainSync(()->ReleaseNotes.showIfNeeded(host,"0.4.0"));SystemClock.sleep(200);ok(find(ui.getRootInActiveWindow(),"更新日志")==null,"release shown once per version");Trip current=Trip.demo();Trip draft=Trip.from(current.json());draft.days=current.days+1;AiPlan plan=AiPlan.parse("{\"days\":[{\"day\":1,\"items\":[{\"name\":\"测试\",\"time\":\"09:00\",\"lat\":null,\"lon\":null}]}]}",draft.days);boolean rejected=false;try{AiExploreUi.prepareImport(current,draft,plan);}catch(IllegalArgumentException expected){rejected=true;}ok(rejected,"AI append rejects changed dates");ok(AiExploreUi.prepareImport(null,draft,plan).days==draft.days,"AI can create new date range");return n;}finally{cfg.reset();cfg.putAll(previousConfig);ts.edit().clear().apply();SharedPreferences.Editor e=ts.edit();for(Map.Entry<String,?> x:old.entrySet()){Object v=x.getValue();if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);}e.commit();if(a!=null){final MainActivity closing=a;in.runOnMainSync(closing::finish);};}}
 private static void capture(Instrumentation in,String name)throws Exception{SystemClock.sleep(300);android.graphics.Bitmap b=in.getUiAutomation().takeScreenshot();if(b!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(in.getTargetContext().getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
 private static AccessibilityNodeInfo find(AccessibilityNodeInfo r,String t){if(r==null)return null;CharSequence v=r.getText();if(v!=null&&v.toString().contains(t))return r;for(int i=0;i<r.getChildCount();i++){AccessibilityNodeInfo x=find(r.getChild(i),t);if(x!=null)return x;}return null;}
 private static AccessibilityNodeInfo wait(UiAutomation u,String t)throws Exception{for(int i=0;i<50;i++){AccessibilityNodeInfo x=find(u.getRootInActiveWindow(),t);if(x!=null)return x;SystemClock.sleep(100);}throw new AssertionError("Missing UI: "+t);}
 private static void click(UiAutomation u,String t)throws Exception{if(!wait(u,t).performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Cannot click "+t);SystemClock.sleep(180);}
}
